import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

function isValidDiscount(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

function calculateDueDate(issueDate, terms = 'NET30') {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  }
  if (terms === 'NET30') {
    return addDays(issueDate, 30);
  }
  if (terms === 'EOM') {
    const [year, month] = issueDate.split('-');
    const nextMonth = parseInt(month) + 1;
    let nextMonthStr = String(nextMonth).padStart(2, '0');
    let nextYearStr = year;
    if (nextMonth > 12) {
      nextMonthStr = '01';
      nextYearStr = String(parseInt(year) + 1);
    }
    const firstDayNextMonth = `${nextYearStr}-${nextMonthStr}-01`;
    return addDays(firstDayNextMonth, -1);
  }
  return null;
}

/**
 * Create an invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!['NET14', 'NET30', 'EOM'].includes(terms)) return fail('TERMS_INVALID');

  if (!lines || !Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const invoiceLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    const discount = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (discount > 0) {
      invoiceLine.discountPercent = discount;
    }
    invoiceLines.push(invoiceLine);
  }

  const dueDate = calculateDueDate(issueDate, terms);

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single line item: qty times unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }
  return ok(line.qty * line.unitPrice);
}

/**
 * Calculate totals for an invoice: subtotal, discount, VAT, and total.
 * VAT is calculated per line on the amount after discount, rounded per line.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }}
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const result = lineTotal(line);
    if (!result.ok) return result;
    const amount = result.value;
    subtotal += amount;

    let lineDiscount = 0;
    if (line.discountPercent && line.discountPercent > 0) {
      lineDiscount = Math.round(amount * (line.discountPercent / 100));
      discount += lineDiscount;
    }

    const amountAfterDiscount = amount - lineDiscount;
    if (line.vatRate && line.vatRate > 0) {
      const lineVAT = roundCents(amountAfterDiscount * (line.vatRate / 100));
      vat += lineVAT;
    }
  }

  const total = Math.max(0, subtotal - discount + vat);

  return ok({
    subtotal,
    discount,
    vat,
    total,
  });
}

/**
 * Add or increase a line item on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number, discountPercent?: number }>, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
    if (discountPercent !== undefined) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'draft',
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    lines: newLines,
  });
}

/**
 * Remove a line item from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }>, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.map((line) => ({ ...line })).filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'draft',
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a unique number and changing status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - All invoice numbers already issued
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

