    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 1 }],
  }).value;

  const r = applyVoucher(invoice, { code: 'LARGE', amount: 100000 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.amount, 100000);
});

test('applyVoucher preserves all invoice data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
    terms: 'NET14',
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 500 }).value;

  assert.equal(withVoucher.customerId, 'C-001');
  assert.equal(withVoucher.issueDate, '2026-10-07');
  assert.equal(withVoucher.status, 'draft');
  assert.equal(withVoucher.terms, 'NET14');
  assert.equal(withVoucher.lines.length, 2);
});

test('invoiceTotals with discount and voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  // DES-HOUR: 17000, discount: 1700, amount after discount: 15300, VAT: 3213, Total: 18513
  const withVoucher = applyVoucher(invoice, { code: 'VOUCHER', amount: 2000 }).value;
  const r = invoiceTotals(withVoucher);

  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 17000);
  assert.equal(r.value.discount, 1700);
  assert.equal(r.value.vat, 3213);
  assert.equal(r.value.voucher, 2000);
  assert.equal(r.value.total, 16513);
});

test('invoiceTotals with multiple lines and voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  // Subtotal: 45500, VAT: 9555, Total without voucher: 55055
  const withVoucher = applyVoucher(invoice, { code: 'MULTI', amount: 5000 }).value;
  const r = invoiceTotals(withVoucher);

  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 45500);
  assert.equal(r.value.vat, 9555);
  assert.equal(r.value.voucher, 5000);
  assert.equal(r.value.total, 50055);
});

