test('invoiceTotals with voucher and tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  // DES-HOUR: 17000, discount: 850 (5%), amount after discount: 16150, VAT: 3392, Total: 19542
  const withVoucher = applyVoucher(invoice, { code: 'GOLD', amount: 1500 }).value;
  const r = invoiceTotals(withVoucher);

  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 17000);
  assert.equal(r.value.discount, 850);
  assert.equal(r.value.vat, 3392);
  assert.equal(r.value.voucher, 1500);
  assert.equal(r.value.total, 18042);
});

test('invoiceTotals with VAT-exempt items and voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  // WORKSHOP-DAY: 60000, VAT: 0, Total: 60000
  const withVoucher = applyVoucher(invoice, { code: 'WORKSHOP', amount: 5000 }).value;
  const r = invoiceTotals(withVoucher);

  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 60000);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.voucher, 5000);
  assert.equal(r.value.total, 55000);
});

test('invoiceTotals with mixed VAT rates and voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 50 },
    ],
  }).value;

  // DES-HOUR: 8500, VAT: 1785
  // PRINT-A4: 1850, VAT: 166
  // Total: 12301
  const withVoucher = applyVoucher(invoice, { code: 'MIXED', amount: 1000 }).value;
  const r = invoiceTotals(withVoucher);

  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10350);
  assert.equal(r.value.vat, 1951);
  assert.equal(r.value.voucher, 1000);
  assert.equal(r.value.total, 11301);
});

test('voucher amount exactly equals total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  // DES-HOUR: 8500, VAT: 1785, Total: 10285
  const withVoucher = applyVoucher(invoice, { code: 'FULL', amount: 10285 }).value;
  const r = invoiceTotals(withVoucher);

  assert.equal(r.ok, true);
  assert.equal(r.value.total, 0);
});

test('sequential voucher applications fail', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r1 = applyVoucher(invoice, { code: 'FIRST', amount: 1000 });
  assert.equal(r1.ok, true);

  const r2 = applyVoucher(r1.value, { code: 'SECOND', amount: 2000 });
  assert.deepEqual(r2, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('voucher applied before and after edits', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'EDIT', amount: 500 }).value;
  const added = addLine(withVoucher, { sku: 'DEV-HOUR', qty: 1 }).value;

  assert.equal(added.voucher.code, 'EDIT');
  assert.equal(added.voucher.amount, 500);
  assert.equal(added.lines.length, 2);
});

test('invoiceTotals calculates voucher reduction correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;

  // LOGO-PACK: 120000, VAT: 25200, Total: 145200
  const percentages = [10, 25, 50, 75, 90];

  for (const pct of percentages) {
    const amount = Math.round(145200 * (pct / 100));
    const withVoucher = applyVoucher(invoice, { code: `PCT${pct}`, amount }).value;
    const r = invoiceTotals(withVoucher);

    assert.equal(r.ok, true);
    assert.equal(r.value.voucher, amount);
    assert.equal(r.value.total, 145200 - amount);
  }
});

